+        if (status != all_locks_status) {
+            fail("lock bits not sticky (uC write of 0 cleared state)", status, all_locks_status);
         }
         VPRINTF(LOW, "FW: lock bits sticky after uC write of 0 to CPTRA_LOCK\n");
